def zendesk_get_ticket(workspace_id, ticket_id=None, zendesk_ticket_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0039000" if __import__("os").path.isdir("./environment_mix/0039000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request logging + quota helpers (best-effort; no blanket exception) ---
    def _log_request(api_key_id, ws_id, endpoint, status, latency_ms, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "zdrq_" + os.urandom(9).hex().upper(),
            "timestamp": now,
            "endpoint": endpoint,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _day_key(ts_iso):
        if isinstance(ts_iso, str) and len(ts_iso) >= 10:
            return ts_iso[:10]
        return now[:10]

    def _minute_bucket(ts_iso):
        # YYYY-MM-DDTHH:MM
        if isinstance(ts_iso, str) and len(ts_iso) >= 16:
            return ts_iso[:16]
        return now[:16]

    def _count_usage(api_key_id, ws_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return (0, 0, 0)
        d = now[:10]
        m = _minute_bucket(now)
        key_day = 0
        key_min = 0
        ws_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if _day_key(ts) != d:
                continue
            if r.get("workspace_id") == ws_id:
                ws_day += 1
            if r.get("api_key_id") == api_key_id:
                key_day += 1
                if _minute_bucket(ts) == m:
                    key_min += 1
        return (key_min, key_day, ws_day)

    # --- validate inputs ---
    if not isinstance(workspace_id, str) or re.match(r"^zdws_[0-9A-Z]{18,}$", workspace_id) is None:
        # log unauthenticated attempt (if possible)
        _log_request(None, workspace_id if isinstance(workspace_id, str) else None, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is invalid; expected format ^zdws_[0-9A-Z]{18,}$")

    if ticket_id is None and zendesk_ticket_id is None:
        _log_request(None, workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either ticket_id or zendesk_ticket_id must be provided")

    if ticket_id is not None:
        if not isinstance(ticket_id, str) or re.match(r"^zdtkt_[0-9A-Z]{18,}$", ticket_id) is None:
            _log_request(None, workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "ticket_id is invalid; expected format ^zdtkt_[0-9A-Z]{18,}$")
    if zendesk_ticket_id is not None:
        if not isinstance(zendesk_ticket_id, int) or zendesk_ticket_id < 1:
            _log_request(None, workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "zendesk_ticket_id must be an integer >= 1")

    # --- ambient auth resolution: pick any active api key for active workspace with active connection ---
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log_request(None, workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    if ws.get("status") != "active":
        _log_request(None, workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active")

    conns = _load("zendesk_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("workspace_id") == workspace_id), None)
    if conn is None:
        _log_request(None, workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace has no configured Zendesk connection")
    if conn.get("status") != "active":
        _log_request(None, workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Zendesk connection is not active")

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    # choose any active key in this workspace
    api_key = next((k for k in keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if api_key is None:
        _log_request(None, workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this workspace")

    # enforce quotas/rate limits based on request_logs.json
    key_min, key_day, ws_day = _count_usage(api_key.get("id"), workspace_id)
    rpm = api_key.get("requests_per_minute")
    kquota = api_key.get("daily_request_quota")
    wsquota = ws.get("daily_request_quota")
    if not isinstance(rpm, int) or rpm < 1:
        _log_request(api_key.get("id"), workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "API key has invalid requests_per_minute configuration")
    if isinstance(kquota, int) and kquota >= 0 and key_day >= kquota:
        _log_request(api_key.get("id"), workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "API key daily quota exceeded", limit=kquota)
    if isinstance(wsquota, int) and wsquota >= 0 and ws_day >= wsquota:
        _log_request(api_key.get("id"), workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Workspace daily quota exceeded", limit=wsquota)
    if key_min >= rpm:
        _log_request(api_key.get("id"), workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", "API key rate limit exceeded", limit_per_minute=rpm)

    # --- locate ticket in local cache, then "refresh" (offline) by updating sync timestamps ---
    tickets = _load("tickets.json")
    if not isinstance(tickets, list):
        tickets = []
    ticket = None
    if ticket_id is not None:
        ticket = next((t for t in tickets if isinstance(t, dict) and t.get("id") == ticket_id and t.get("workspace_id") == workspace_id), None)
    if ticket is None and zendesk_ticket_id is not None:
        ticket = next((t for t in tickets if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("zendesk_ticket_id") == zendesk_ticket_id), None)

    if ticket is None:
        _log_request(api_key.get("id"), workspace_id, "zendesk_get_ticket", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Ticket not found")

    # Soft-delete handling: deleted/unavailable is represented by status=deleted; still retrievable.
    # Upsert/refresh semantics: update last_synced_at and zendesk_updated_at (offline, best effort).
    changed = False
    if ticket.get("last_synced_at") != now:
        ticket["last_synced_at"] = now
        changed = True
    # If zendesk_updated_at missing, set; otherwise keep (can't contact Zendesk offline) but refresh if absent.
    if ticket.get("zendesk_updated_at") is None:
        ticket["zendesk_updated_at"] = now
        changed = True
    if ticket.get("updated_at") != now:
        ticket["updated_at"] = now
        changed = True

    if changed:
        for i, t in enumerate(tickets):
            if isinstance(t, dict) and t.get("id") == ticket.get("id"):
                tickets[i] = ticket
                break
        _save("tickets.json", tickets)

    # update api key last_used_at on successful call
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            keys[i] = api_key
            break
    _save("api_keys.json", keys)

    resp = {"ticket": ticket}
    _log_request(api_key.get("id"), workspace_id, "zendesk_get_ticket", "ok", (time.time()-t0)*1000)
    return resp

def zendesk_update_ticket(workspace_id, ticket_id=None, zendesk_ticket_id=None, subject=None, description=None, priority=None, type=None, status=None, requester_id=None, assignee_id=None, group_id=None, tags=None, custom_fields=None, problem_zendesk_ticket_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0039000" if __import__("os").path.isdir("./environment_mix/0039000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, api_key_id, ws_id, status_s, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "zdrq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            **({"error_code": error_code} if error_code else {})
        })
        _save("request_logs.json", logs)

    def _usage_counts(logs, api_key_id, ws_id):
        per_key_min = per_key_day = ws_day = 0
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("created_at") or r.get("timestamp"))
            if ts is None:
                continue
            if api_key_id is not None and r.get("api_key_id") == api_key_id and ts >= minute_ago:
                per_key_min += 1
            if ts >= day_start:
                if api_key_id is not None and r.get("api_key_id") == api_key_id:
                    per_key_day += 1
                if ws_id is not None and r.get("workspace_id") == ws_id:
                    ws_day += 1
        return per_key_min, per_key_day, ws_day

    def _gen_id(prefix, rows):
        # ULID-like enough for local store; ensure uniqueness in file.
        base = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        candidate = f"{prefix}_{base}"
        exists = {r.get("id") for r in rows if isinstance(r, dict)}
        if candidate not in exists:
            return candidate
        i = 0
        while True:
            cand = f"{candidate}{i}"
            if cand not in exists:
                return cand
            i += 1

    # ---- validate inputs (schema) ----
    if not isinstance(workspace_id, str) or not re.match(r"^zdws_[0-9A-Z]{18,}$", workspace_id):
        _log("zendesk_update_ticket", None, workspace_id if isinstance(workspace_id, str) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", workspace_id=workspace_id)

    if ticket_id is not None:
        if not isinstance(ticket_id, str) or not re.match(r"^zdtkt_[0-9A-Z]{18,}$", ticket_id):
            _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid ticket_id.", ticket_id=ticket_id)
    if zendesk_ticket_id is not None:
        if not isinstance(zendesk_ticket_id, int) or zendesk_ticket_id < 1:
            _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid zendesk_ticket_id.", zendesk_ticket_id=zendesk_ticket_id)

    if ticket_id is None and zendesk_ticket_id is None:
        _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Missing ticket identifier: supply ticket_id or zendesk_ticket_id.")

    enum_priority = {"low", "normal", "high", "urgent"}
    enum_type = {"question", "incident", "problem", "task"}
    enum_status = {"new", "open", "pending", "hold", "solved", "closed", "deleted"}

    if priority is not None and (not isinstance(priority, str) or priority not in enum_priority):
        _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid priority.", priority=priority)
    if type is not None and (not isinstance(type, str) or type not in enum_type):
        _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid type.", type=type)
    if status is not None and (not isinstance(status, str) or status not in enum_status):
        _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", status=status)

    if subject is not None and not isinstance(subject, str):
        _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid subject type; expected string.", subject=subject)
    if description is not None and not isinstance(description, str):
        _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid description type; expected string.", description=description)

    for nm, v in [("requester_id", requester_id), ("assignee_id", assignee_id), ("group_id", group_id), ("problem_zendesk_ticket_id", problem_zendesk_ticket_id)]:
        if v is not None and (not isinstance(v, int) or v < 1):
            _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Invalid {nm}.", **{nm: v})

    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(t, str)) for t in tags):
            _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid tags; expected array of strings.", tags=tags)

    if custom_fields is not None and not isinstance(custom_fields, dict):
        _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid custom_fields; expected object.", custom_fields=custom_fields)

    updatable = {
        "subject": subject, "description": description, "priority": priority, "type": type, "status": status,
        "requester_id": requester_id, "assignee_id": assignee_id, "group_id": group_id,
        "tags": tags, "custom_fields": custom_fields, "problem_zendesk_ticket_id": problem_zendesk_ticket_id
    }
    if all(v is None for v in updatable.values()):
        _log("zendesk_update_ticket", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No updatable fields supplied.")

    # ---- ambient auth resolution (must not require explicit credential param) ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    conns = _load("zendesk_connections.json")
    tickets = _load("tickets.json")
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    ws = None
    if isinstance(workspaces, list):
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == workspace_id:
                ws = w
                break
    if not ws:
        _log("zendesk_update_ticket", None, workspace_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") != "active":
        _log("zendesk_update_ticket", None, workspace_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_id=workspace_id)

    # Must authenticate via an active api_keys row; since no param, choose a working key for this workspace.
    key_row = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("workspace_id") != workspace_id:
                continue
            if k.get("status") != "active":
                continue
            # ensure numeric constraints exist/valid-ish
            rpm = k.get("requests_per_minute")
            dq = k.get("daily_request_quota")
            if not isinstance(rpm, int) or rpm < 1:
                continue
            if not isinstance(dq, int) or dq < 0:
                continue
            key_row = k
            break
    if not key_row:
        _log("zendesk_update_ticket", None, workspace_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this workspace.", workspace_id=workspace_id)

    # workspace must have exactly one zendesk_connections row; it must be active
    conn = None
    if isinstance(conns, list):
        matches = [c for c in conns if isinstance(c, dict) and c.get("workspace_id") == workspace_id]
        # exactly one required; but for availability, find the active one and also validate uniqueness
        if len(matches) != 1:
            _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "CONFLICT")
            return _err("CONFLICT", "Workspace must have exactly one Zendesk connection row.", workspace_id=workspace_id, found=len(matches))
        if matches[0].get("status") != "active":
            _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "NOT_FOUND")
            return _err("NOT_FOUND", "Workspace Zendesk connection not found or not active.", workspace_id=workspace_id)
        conn = matches[0]
    else:
        _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace Zendesk connection not found or not active.", workspace_id=workspace_id)

    # ---- rate limit / quota enforcement ----
    per_key_min, per_key_day, ws_day = _usage_counts(logs, key_row.get("id"), workspace_id)
    if per_key_min >= int(key_row.get("requests_per_minute", 0)):
        _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Per-key rate limit exceeded.", requests_per_minute=key_row.get("requests_per_minute"), used_last_minute=per_key_min)
    if per_key_day >= int(key_row.get("daily_request_quota", 0)):
        _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Per-key daily request quota exceeded.", daily_request_quota=key_row.get("daily_request_quota"), used_today=per_key_day)
    if ws_day >= int(ws.get("daily_request_quota", 0)):
        _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Workspace daily request quota exceeded.", daily_request_quota=ws.get("daily_request_quota"), used_today=ws_day)

    # ---- locate ticket ----
    ticket = None
    idx = None
    if not isinstance(tickets, list):
        tickets = []
    for i, t in enumerate(tickets):
        if not isinstance(t, dict):
            continue
        if t.get("workspace_id") != workspace_id:
            continue
        if ticket_id is not None and t.get("id") == ticket_id:
            ticket, idx = t, i
            break
        if ticket is None and zendesk_ticket_id is not None and t.get("zendesk_ticket_id") == zendesk_ticket_id:
            ticket, idx = t, i
            # keep searching in case ticket_id also provided? prefer exact id match; but if ticket_id absent this is fine.
            if ticket_id is None:
                break
    if not ticket:
        _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Target ticket not found in cache for this workspace.", workspace_id=workspace_id, ticket_id=ticket_id, zendesk_ticket_id=zendesk_ticket_id)

    # soft-delete rule: prevent updates that would add comments is elsewhere, but allow status change? For update, allow setting deleted, but if currently deleted only allow no-op or keep deleted.
    if ticket.get("status") == "deleted" and status is not None and status != "deleted":
        _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot transition a deleted ticket to another status.", from_status="deleted", to_status=status)

    # lifecycle transitions for status updates
    transitions = {
        "new": ["open", "pending", "hold", "solved", "closed", "deleted"],
        "open": ["pending", "hold", "solved", "closed", "deleted"],
        "pending": ["open", "hold", "solved", "closed", "deleted"],
        "hold": ["open", "pending", "solved", "closed", "deleted"],
        "solved": ["open", "closed", "deleted"],
        "closed": ["open", "deleted"],
        "deleted": []
    }
    if status is not None:
        cur = ticket.get("status")
        if cur not in transitions:
            _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Ticket has invalid cached status.", status=cur)
        if status != cur and status not in transitions.get(cur, []):
            _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Requested status transition is not allowed.", from_status=cur, to_status=status)

    # ---- apply mutation (simulate Zendesk accept) ----
    changed = False
    updated_fields = {}

    def _set_field(k, v):
        nonlocal changed
        if v is None:
            return
        if ticket.get(k) != v:
            ticket[k] = v
            changed = True
            updated_fields[k] = v

    _set_field("subject", subject)
    _set_field("description", description)
    _set_field("priority", priority)
    _set_field("type", type)
    _set_field("requester_id", requester_id)
    _set_field("assignee_id", assignee_id)
    _set_field("group_id", group_id)
    if tags is not None:
        # store non-null array
        _set_field("tags", list(tags))
    if custom_fields is not None:
        _set_field("custom_fields", dict(custom_fields))
    _set_field("problem_zendesk_ticket_id", problem_zendesk_ticket_id)
    if status is not None:
        _set_field("status", status)

    if not changed:
        # idempotent update: still counts as successful request; update last_used_at etc, but no data row change required beyond timestamps
        ticket["updated_at"] = now
        ticket["zendesk_updated_at"] = now
        ticket["last_synced_at"] = now
        tickets[idx] = ticket
        changed = True  # ensures persistence of timestamp touch

    else:
        ticket["updated_at"] = now
        ticket["zendesk_updated_at"] = now
        ticket["last_synced_at"] = now
        tickets[idx] = ticket

    # persist
    _save("tickets.json", tickets)

    # update key usage
    if isinstance(api_keys, list):
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                api_keys[i] = k
                break
        _save("api_keys.json", api_keys)

    _log("zendesk_update_ticket", key_row.get("id"), workspace_id, "success")

    # return updated payload
    return {
        "ticket": ticket,
        "workspace": {"id": ws.get("id"), "name": ws.get("name"), "zendesk_subdomain": ws.get("zendesk_subdomain")},
        "connection": {"id": conn.get("id"), "auth_type": conn.get("auth_type"), "status": conn.get("status")},
        "updated_fields": updated_fields
    }

def zendesk_create_ticket(workspace_id, subject, description, priority=None, type=None, status=None, requester_id=None, assignee_id=None, group_id=None, tags=None, custom_fields=None, problem_zendesk_ticket_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0039000" if __import__("os").path.isdir("./environment_mix/0039000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(api_key_id, ws_id, endpoint, status_s, latency_ms, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "zdrq_" + os.urandom(9).hex().upper(),
            "timestamp": now,
            "endpoint": endpoint,
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    def _minute_bucket(ts_iso):
        return ts_iso[:16] if isinstance(ts_iso, str) and len(ts_iso) >= 16 else now[:16]

    def _count_usage(api_key_id, ws_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return (0, 0, 0)
        d = now[:10]
        m = _minute_bucket(now)
        key_day = key_min = ws_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            if not (isinstance(ts, str) and len(ts) >= 10 and ts[:10] == d):
                continue
            if r.get("workspace_id") == ws_id:
                ws_day += 1
            if r.get("api_key_id") == api_key_id:
                key_day += 1
                if _minute_bucket(ts) == m:
                    key_min += 1
        return (key_min, key_day, ws_day)

    # validate inputs
    if not isinstance(workspace_id, str) or re.match(r"^zdws_[0-9A-Z]{18,}$", workspace_id) is None:
        _log_request(None, workspace_id if isinstance(workspace_id, str) else None, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is invalid; expected format ^zdws_[0-9A-Z]{18,}$")
    if not isinstance(subject, str) or subject == "":
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subject is required and must be a non-empty string")
    if not isinstance(description, str) or description == "":
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description is required and must be a non-empty string")

    if priority is not None and priority not in ["low", "normal", "high", "urgent"]:
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "priority must be one of: low, normal, high, urgent")
    if type is not None and type not in ["question", "incident", "problem", "task"]:
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "type must be one of: question, incident, problem, task")
    if status is not None and status not in ["new", "open", "pending", "hold", "solved", "closed", "deleted"]:
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: new, open, pending, hold, solved, closed, deleted")
    for nm, v in [("requester_id", requester_id), ("assignee_id", assignee_id), ("group_id", group_id), ("problem_zendesk_ticket_id", problem_zendesk_ticket_id)]:
        if v is not None and (not isinstance(v, int) or v < 1):
            _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{nm} must be an integer >= 1")
    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(x, str)) for x in tags):
            _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of strings")
    if custom_fields is not None and not isinstance(custom_fields, dict):
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "custom_fields must be an object")

    # initial status restriction
    if status is None:
        status = "new"
    if status not in ["new", "open", "pending", "hold"]:
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Initial status must be one of: new, open, pending, hold")

    # ambient auth
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active")

    conns = _load("zendesk_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("workspace_id") == workspace_id), None)
    if conn is None or conn.get("status") != "active":
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace has no active Zendesk connection")

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    api_key = next((k for k in keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if api_key is None:
        _log_request(None, workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this workspace")

    # quotas
    key_min, key_day, ws_day = _count_usage(api_key.get("id"), workspace_id)
    rpm = api_key.get("requests_per_minute")
    kquota = api_key.get("daily_request_quota")
    wsquota = ws.get("daily_request_quota")
    if isinstance(kquota, int) and kquota >= 0 and key_day >= kquota:
        _log_request(api_key.get("id"), workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "API key daily quota exceeded", limit=kquota)
    if isinstance(wsquota, int) and wsquota >= 0 and ws_day >= wsquota:
        _log_request(api_key.get("id"), workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Workspace daily quota exceeded", limit=wsquota)
    if isinstance(rpm, int) and key_min >= rpm:
        _log_request(api_key.get("id"), workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", "API key rate limit exceeded", limit_per_minute=rpm)

    tickets = _load("tickets.json")
    if not isinstance(tickets, list):
        tickets = []

    # simulate Zendesk assigning a new numeric id: max+1 within workspace
    max_zid = 0
    for t in tickets:
        if isinstance(t, dict) and t.get("workspace_id") == workspace_id:
            zid = t.get("zendesk_ticket_id")
            if isinstance(zid, int) and zid > max_zid:
                max_zid = zid
    new_zendesk_id = max_zid + 1
    if new_zendesk_id < 1:
        new_zendesk_id = 1

    # enforce unique(workspace_id, zendesk_ticket_id)
    if any(isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("zendesk_ticket_id") == new_zendesk_id for t in tickets):
        _log_request(api_key.get("id"), workspace_id, "zendesk_create_ticket", "error", (time.time()-t0)*1000, "CONFLICT")
        return _err("CONFLICT", "Zendesk ticket id collision; retry")

    new_ticket = {
        "id": "zdtkt_" + os.urandom(12).hex().upper(),
        "workspace_id": workspace_id,
        "zendesk_ticket_id": new_zendesk_id,
        "subject": subject,
        "description": description,
        "priority": priority,
        "type": type,
        "status": status,
        "requester_id": requester_id,
        "assignee_id": assignee_id,
        "group_id": group_id,
        "tags": tags if tags is not None else [],
        "custom_fields": custom_fields,
        "problem_zendesk_ticket_id": problem_zendesk_ticket_id,
        "zendesk_created_at": now,
        "zendesk_updated_at": now,
        "last_synced_at": now,
        "created_at": now,
        "updated_at": now,
    }

    tickets.append(new_ticket)
    _save("tickets.json", tickets)

    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            keys[i] = api_key
            break
    _save("api_keys.json", keys)

    _log_request(api_key.get("id"), workspace_id, "zendesk_create_ticket", "ok", (time.time()-t0)*1000)
    return {"ticket": new_ticket}

