    if isinstance(rpm, int) and key_min >= rpm:
        _log_request(api_key.get("id"), workspace_id, "zendesk_add_private_note", "error", (time.time()-t0)*1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", "API key rate limit exceeded", limit_per_minute=rpm)

    tickets = _load("tickets.json")
    if not isinstance(tickets, list):
        tickets = []
