            if isinstance(t, dict) and t.get("id") == ticket_id and t.get("workspace_id") == workspace_id:
                ticket = t
                tidx = i
                break
    if ticket is None and zendesk_ticket_id is not None:
        for i, t in enumerate(tickets):
            if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("zendesk_ticket_id") == zendesk_ticket_id:
                ticket = t
                tidx = i
                break
    if ticket is None:
        _log_request(api_key.get("id"), workspace_id, "zendesk_add_private_note", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Ticket not found")

