def zendesk_add_public_note(workspace_id, body, ticket_id=None, zendesk_ticket_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0039000" if __import__("os").path.isdir("./environment_mix/0039000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers for request logging / quota ----
    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(api_key_id, workspace_id_for_log, endpoint, status, latency_ms):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = "zdrq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        logs.append({
            "id": rid,
            "workspace_id": workspace_id_for_log,
            "api_key_id": api_key_id,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _count_usage(logs, api_key_id, workspace_id_for_counts):
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        per_key_min = 0
        per_key_day = 0
        ws_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= day_start:
                if r.get("workspace_id") == workspace_id_for_counts:
                    ws_day += 1
                if r.get("api_key_id") == api_key_id:
                    per_key_day += 1
            if ts >= minute_ago and r.get("api_key_id") == api_key_id:
                per_key_min += 1
        return per_key_min, per_key_day, ws_day

    endpoint = "zendesk_add_public_note"

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^zdws_[0-9A-Z]{18,}$", workspace_id):
        # attempt to log even on validation (best-effort with any active key)
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        logs = _load("request_logs.json")
        active_combo = None
        for k in api_keys if isinstance(api_keys, list) else []:
            if isinstance(k, dict) and k.get("status") == "active":
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id") and w.get("status") == "active"), None)
                if ws:
                    active_combo = (k, ws)
                    break
        if active_combo:
            _log_request(active_combo[0].get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")

    if not isinstance(body, str) or body.strip() == "":
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        logs = _load("request_logs.json")
        active_combo = None
        for k in api_keys if isinstance(api_keys, list) else []:
            if isinstance(k, dict) and k.get("status") == "active":
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id") and w.get("status") == "active"), None)
                if ws:
                    active_combo = (k, ws)
                    break
        if active_combo:
            _log_request(active_combo[0].get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "body must be a non-empty string", field="body")

    if ticket_id is None and zendesk_ticket_id is None:
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        active_combo = None
        for k in api_keys if isinstance(api_keys, list) else []:
            if isinstance(k, dict) and k.get("status") == "active":
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id") and w.get("status") == "active"), None)
                if ws:
                    active_combo = (k, ws)
                    break
        if active_combo:
            _log_request(active_combo[0].get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Either ticket_id or zendesk_ticket_id must be provided")

    if ticket_id is not None:
        if not isinstance(ticket_id, str) or not re.match(r"^zdtkt_[0-9A-Z]{18,}$", ticket_id):
            api_keys = _load("api_keys.json")
            workspaces = _load("workspaces.json")
            active_combo = None
            for k in api_keys if isinstance(api_keys, list) else []:
                if isinstance(k, dict) and k.get("status") == "active":
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id") and w.get("status") == "active"), None)
                    if ws:
                        active_combo = (k, ws)
                        break
            if active_combo:
                _log_request(active_combo[0].get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "ticket_id is malformed", field="ticket_id")

    if zendesk_ticket_id is not None:
        if not isinstance(zendesk_ticket_id, int) or zendesk_ticket_id < 1:
            api_keys = _load("api_keys.json")
            workspaces = _load("workspaces.json")
            active_combo = None
            for k in api_keys if isinstance(api_keys, list) else []:
                if isinstance(k, dict) and k.get("status") == "active":
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id") and w.get("status") == "active"), None)
                    if ws:
                        active_combo = (k, ws)
                        break
            if active_combo:
                _log_request(active_combo[0].get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "zendesk_ticket_id must be an integer >= 1", field="zendesk_ticket_id")

    # ---- authenticate ambient (find active api key in this workspace) and enforce quotas ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    connections = _load("zendesk_connections.json")
    logs = _load("request_logs.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        # log with any active key if possible
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
    if ws.get("status") != "active":
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("workspace_id") == workspace_id), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Workspace is not active", workspace_id=workspace_id)

    # Must authenticate via an active api key in this workspace (ambient)
    key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key:
        # If none for this workspace, per rules we can only return UNAUTHORIZED
        # Still log with any active key elsewhere if present (best-effort).
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No active API key available for this workspace", workspace_id=workspace_id)

    # Enforce per-key and per-workspace quotas (requests-per-minute, daily quotas)
    if not isinstance(logs, list):
        logs = []
    per_key_min, per_key_day, ws_day = _count_usage(logs, key.get("id"), workspace_id)
    rpm = key.get("requests_per_minute")
    kday_quota = key.get("daily_request_quota")
    ws_quota = ws.get("daily_request_quota")

    if isinstance(rpm, int) and per_key_min >= rpm:
        _log_request(key.get("id"), workspace_id, endpoint, "rate_limited", (time.time() - t0) * 1000)
        return _err("RATE_LIMIT", "Per-key requests_per_minute exceeded", limit=rpm)
    if isinstance(kday_quota, int) and kday_quota >= 0 and per_key_day >= kday_quota:
        _log_request(key.get("id"), workspace_id, endpoint, "quota_exceeded", (time.time() - t0) * 1000)
        return _err("QUOTA_EXCEEDED", "Per-key daily_request_quota exceeded", quota=kday_quota)
    if isinstance(ws_quota, int) and ws_quota >= 0 and ws_day >= ws_quota:
        _log_request(key.get("id"), workspace_id, endpoint, "quota_exceeded", (time.time() - t0) * 1000)
        return _err("QUOTA_EXCEEDED", "Workspace daily_request_quota exceeded", quota=ws_quota)

    # Connection must exist and be active
    conn = next((c for c in connections if isinstance(c, dict) and c.get("workspace_id") == workspace_id), None)
    if not conn:
        _log_request(key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Zendesk connection not found for workspace", workspace_id=workspace_id)
    if conn.get("status") != "active":
        _log_request(key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Zendesk connection is not active", status=conn.get("status"))

    # ---- find ticket in cache ----
    tickets = _load("tickets.json")
    ticket = None
    if isinstance(tickets, list):
        if ticket_id is not None:
            ticket = next((t for t in tickets if isinstance(t, dict) and t.get("id") == ticket_id and t.get("workspace_id") == workspace_id), None)
        if ticket is None and zendesk_ticket_id is not None:
            ticket = next((t for t in tickets if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("zendesk_ticket_id") == zendesk_ticket_id), None)
    if not ticket:
        _log_request(key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Ticket not found", workspace_id=workspace_id)

    if ticket.get("status") == "deleted":
        _log_request(key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("CONFLICT", "Ticket is deleted and not writable", ticket_id=ticket.get("id"), zendesk_ticket_id=ticket.get("zendesk_ticket_id"))

    # ---- create comment row (local cache write-through) ----
    comments = _load("ticket_comments.json")
    if not isinstance(comments, list):
        comments = []

    # Generate id
    new_id = "zdcmt_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    ztid = ticket.get("zendesk_ticket_id")

    comment_row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "ticket_id": ticket.get("id"),
        "zendesk_ticket_id": ztid,
        "zendesk_comment_id": None,
        "visibility": "public",
        "author_zendesk_user_id": None,
        "body": body,
        "via": "api",
        "is_from_integration": True,
        "zendesk_created_at": now,
        "created_at": now,
        "updated_at": now
    }
    comments.append(comment_row)
    _save("ticket_comments.json", comments)

    # Update ticket sync timestamps (simulate Zendesk update)
    # NOTE: do not change ticket.status here.
    ticket["zendesk_updated_at"] = now
    ticket["last_synced_at"] = now
    ticket["updated_at"] = now
    _save("tickets.json", tickets)

    # Update key last_used_at on success
    key["last_used_at"] = now
    key["updated_at"] = key.get("updated_at") or now
    _save("api_keys.json", api_keys)

    latency_ms = (time.time() - t0) * 1000
    _log_request(key.get("id"), workspace_id, endpoint, "ok", latency_ms)

    return {
        "ticket": ticket,
        "comment": comment_row
    }

def zendesk_search(workspace_id, query, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0039000" if __import__("os").path.isdir("./environment_mix/0039000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(api_key_id, workspace_id_for_log, endpoint, status, latency_ms):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = "zdrq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
        logs.append({
            "id": rid,
            "workspace_id": workspace_id_for_log,
            "api_key_id": api_key_id,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _count_usage(logs, api_key_id, workspace_id_for_counts):
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        per_key_min = 0
        per_key_day = 0
        ws_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= day_start:
                if r.get("workspace_id") == workspace_id_for_counts:
                    ws_day += 1
                if r.get("api_key_id") == api_key_id:
                    per_key_day += 1
            if ts >= minute_ago and r.get("api_key_id") == api_key_id:
                per_key_min += 1
        return per_key_min, per_key_day, ws_day

    def _encode_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or cur.strip() == "":
            raise ValueError("malformed")
        s = cur.strip()
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
        obj = json.loads(raw.decode("utf-8"))
        off = obj.get("offset")
        if not isinstance(off, int) or off < 0:
            raise ValueError("malformed")
        return off

    endpoint = "zendesk_search"

    # ---- validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^zdws_[0-9A-Z]{18,}$", workspace_id):
        api_keys = _load("api_keys.json")
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "workspace_id is malformed", field="workspace_id")

    if not isinstance(query, str) or query.strip() == "":
        api_keys = _load("api_keys.json")
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        api_keys = _load("api_keys.json")
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")

    # server-side maximum (<=100)
    if limit > 100:
        limit = 100

    if sort_by is None:
        sort_by = "updated_at"
    if sort_by not in ("created_at", "updated_at", "priority", "status"):
        api_keys = _load("api_keys.json")
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Unsupported sort_by", field="sort_by")

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        api_keys = _load("api_keys.json")
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Unsupported sort_order", field="sort_order")

    try:
        offset = _decode_cursor(cursor)
    except ValueError:
        api_keys = _load("api_keys.json")
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    # ---- authenticate ambient and enforce quotas ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    connections = _load("zendesk_connections.json")
    logs = _load("request_logs.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
    if ws.get("status") != "active":
        key_guess = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and k.get("workspace_id") == workspace_id), None)
        if key_guess:
            _log_request(key_guess.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Workspace is not active", workspace_id=workspace_id)

    key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
    if not key:
        any_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
        if any_key:
            _log_request(any_key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No active API key available for this workspace", workspace_id=workspace_id)

    if not isinstance(logs, list):
        logs = []
    per_key_min, per_key_day, ws_day = _count_usage(logs, key.get("id"), workspace_id)
    rpm = key.get("requests_per_minute")
    kday_quota = key.get("daily_request_quota")
    ws_quota = ws.get("daily_request_quota")

    if isinstance(rpm, int) and per_key_min >= rpm:
        _log_request(key.get("id"), workspace_id, endpoint, "rate_limited", (time.time() - t0) * 1000)
        return _err("RATE_LIMIT", "Per-key requests_per_minute exceeded", limit=rpm)
    if isinstance(kday_quota, int) and kday_quota >= 0 and per_key_day >= kday_quota:
        _log_request(key.get("id"), workspace_id, endpoint, "quota_exceeded", (time.time() - t0) * 1000)
        return _err("QUOTA_EXCEEDED", "Per-key daily_request_quota exceeded", quota=kday_quota)
    if isinstance(ws_quota, int) and ws_quota >= 0 and ws_day >= ws_quota:
        _log_request(key.get("id"), workspace_id, endpoint, "quota_exceeded", (time.time() - t0) * 1000)
        return _err("QUOTA_EXCEEDED", "Workspace daily_request_quota exceeded", quota=ws_quota)

    conn = next((c for c in connections if isinstance(c, dict) and c.get("workspace_id") == workspace_id), None)
    if not conn or conn.get("status") != "active":
        _log_request(key.get("id"), workspace_id, endpoint, "error", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Zendesk connection not found or not active", workspace_id=workspace_id)

    # ---- execute local search over cached tickets/comments ----
    tickets = _load("tickets.json")
    comments = _load("ticket_comments.json")
    if not isinstance(tickets, list):
        tickets = []
    if not isinstance(comments, list):
        comments = []

    q = query.strip().lower()

    # Pre-index comments by ticket_id for optional searching in bodies.
    # Always include comments body matching as part of local server's "optionally ticket_comments.body"
    comments_by_ticket = {}
    for c in comments:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") != workspace_id:
            continue
        tid = c.get("ticket_id")
        if not tid:
            continue
        comments_by_ticket.setdefault(tid, []).append(c)

    def _ticket_matches(t):
        if t.get("workspace_id") != workspace_id:
            return False
        # Soft-deleted tickets still searchable; Zendesk search could return them, but local cache uses status='deleted'
        subject = (t.get("subject") or "")
        desc = (t.get("description") or "")
        tags = t.get("tags") if isinstance(t.get("tags"), list) else []
        hay = " ".join([subject, desc, " ".join([str(x) for x in tags if isinstance(x, str)])]).lower()
        if q in hay:
            return True
        # also search comments bodies (optional; enabled here)
        for c in comments_by_ticket.get(t.get("id"), []):
            b = c.get("body") or ""
            if isinstance(b, str) and q in b.lower():
                return True
        return False

    matched = [t for t in tickets if isinstance(t, dict) and _ticket_matches(t)]

    # sorting
    priority_order = {"low": 0, "normal": 1, "high": 2, "urgent": 3, None: -1}
    status_order = {"new": 0, "open": 1, "pending": 2, "hold": 3, "solved": 4, "closed": 5, "deleted": 6, None: 999}

    def _sort_key(t):
        if sort_by in ("created_at", "updated_at"):
            # Prefer zendesk_* if present, else local created/updated
            ts = t.get("zendesk_created_at") if sort_by == "created_at" else t.get("zendesk_updated_at")
            ts = ts or (t.get("created_at") if sort_by == "created_at" else t.get("updated_at"))
            parsed = _parse_ts(ts)
            # place unknowns last for desc, first for asc using sentinel
            return parsed or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if sort_by == "priority":
            return priority_order.get(t.get("priority"), -1)
        if sort_by == "status":
            return status_order.get(t.get("status"), 999)
        return 0

    reverse = (sort_order == "desc")
    matched.sort(key=_sort_key, reverse=reverse)

    total = len(matched)
    page = matched[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    # Update key last_used_at on success
    key["last_used_at"] = now
    key["updated_at"] = key.get("updated_at") or now
    _save("api_keys.json", api_keys)

    latency_ms = (time.time() - t0) * 1000
    _log_request(key.get("id"), workspace_id, endpoint, "ok", latency_ms)

    return {
        "tickets": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order
        }
    }

def zendesk_get_ticket_details(workspace_id, ticket_id=None, zendesk_ticket_id=None, include_comments=None, comments_limit=None, comments_cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0039000" if __import__("os").path.isdir("./environment_mix/0039000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
