        try:
            raw = base64.urlsafe_b64decode(comments_cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("offset:"):
                offset = int(s.split(":", 1)[1])
                if offset < 0:
                    offset = 0
            else:
                # opaque foreign cursor: treat as no offset (don't error)
                offset = 0
        except Exception:
            # opaque foreign cursor: treat as no offset (don't error)
            offset = 0

    # Resolve auth context (ambient)
    api_key_row, ws_row, conn_row = _resolve_auth_for_workspace(workspace_id)
    if not api_key_row or not ws_row:
