        ws_map = {w.get("id"): w for w in (workspaces if isinstance(workspaces, list) else []) if isinstance(w, dict)}
        conn_by_ws = {}
        for c in (conns if isinstance(conns, list) else []):
            if isinstance(c, dict):
                conn_by_ws[c.get("workspace_id")] = c

