        _log("zendesk_search_tickets", None, workspace_id if isinstance(workspace_id, str) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid api_key format.", api_key=api_key)

    if not isinstance(workspace_id, str) or not re.match(r"^zdws_[0-9A-Z]{18,}$", workspace_id):
        _log("zendesk_search_tickets", None, workspace_id if isinstance(workspace_id, str) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", workspace_id=workspace_id)

    if not isinstance(query, str) or len(query.strip()) < 1:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid query; must be non-empty string.", query=query)

    if include_comments is None:
        include_comments = False
    if not isinstance(include_comments, bool):
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid include_comments; expected boolean.", include_comments=include_comments)

    enum_status = {"new", "open", "pending", "hold", "solved", "closed", "deleted"}
    enum_type = {"question", "incident", "problem", "task"}
    enum_priority = {"low", "normal", "high", "urgent"}

    def _validate_enum_list(name, v, allowed):
        if v is None:
            return None
        if not isinstance(v, list) or any((not isinstance(x, str) or x not in allowed) for x in v):
            return _err("VALIDATION_ERROR", f"Invalid {name}.", **{name: v})
        return None

    e = _validate_enum_list("status", status, enum_status)
    if e:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return e
    e = _validate_enum_list("type", type, enum_type)
    if e:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return e
    e = _validate_enum_list("priority", priority, enum_priority)
    if e:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return e

    for nm, v in [("requester_id", requester_id), ("assignee_id", assignee_id), ("group_id", group_id)]:
        if v is not None and (not isinstance(v, int) or v < 1):
            _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"Invalid {nm}.", **{nm: v})

    def _validate_str_list(name, v):
        if v is None:
            return None
        if not isinstance(v, list) or any((not isinstance(x, str)) for x in v):
            return _err("VALIDATION_ERROR", f"Invalid {name}; expected array of strings.", **{name: v})
        return None

    e = _validate_str_list("tags_any", tags_any)
    if e:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return e
    e = _validate_str_list("tags_all", tags_all)
    if e:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return e

    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid page; must be integer >= 1.", page=page)
    if not isinstance(page_size, int) or page_size < 1:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid page_size; must be integer >= 1.", page_size=page_size)

    # server-side hard cap (<=100) even if client asks more
    page_size = min(page_size, 100)

    if sort_by is None:
        sort_by = "relevance"
    if sort_order is None:
        sort_order = "desc"
    if sort_by not in {"relevance", "zendesk_updated_at", "zendesk_created_at"}:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_by.", sort_by=sort_by)
    if sort_order not in {"asc", "desc"}:
        _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_order.", sort_order=sort_order)

    updated_since_dt = None
    if updated_since is not None:
        if not isinstance(updated_since, str):
            _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid updated_since; expected RFC3339 datetime string.", updated_since=updated_since)
        updated_since_dt = _parse_ts(updated_since)
        if updated_since_dt is None:
            _log("zendesk_search_tickets", None, workspace_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid updated_since datetime format.", updated_since=updated_since)

    # ---- authenticate api_key (by id or client-visible value) ----
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    conns = _load("zendesk_connections.json")
    tickets = _load("tickets.json")
    comments = _load("ticket_comments.json")
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    ws = None
    if isinstance(workspaces, list):
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == workspace_id:
                ws = w
                break
    if not ws:
        _log("zendesk_search_tickets", None, workspace_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") != "active":
        _log("zendesk_search_tickets", None, workspace_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_id=workspace_id)

    key_row = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == api_key:
                key_row = k
                break
            # allow matching by client-visible value if present (never by hash)
            if k.get("key_prefix") == api_key:
                key_row = k
                break
    if not key_row or key_row.get("workspace_id") != workspace_id:
        _log("zendesk_search_tickets", None, workspace_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key not recognized for this workspace.", workspace_id=workspace_id)
    if key_row.get("status") != "active":
        _log("zendesk_search_tickets", key_row.get("id"), workspace_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active.", api_key_id=key_row.get("id"))
    if ws.get("status") != "active":
        _log("zendesk_search_tickets", key_row.get("id"), workspace_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_id=workspace_id)

    # connection must exist and be active, and exactly one row per workspace
    if not isinstance(conns, list):
        conns = []
    matches = [c for c in conns if isinstance(c, dict) and c.get("workspace_id") == workspace_id]
    if len(matches) != 1:
        _log("zendesk_search_tickets", key_row.get("id"), workspace_id, "error", "CONFLICT")
        return _err("CONFLICT", "Workspace must have exactly one Zendesk connection row.", workspace_id=workspace_id, found=len(matches))
    if matches[0].get("status") != "active":
        _log("zendesk_search_tickets", key_row.get("id"), workspace_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace Zendesk connection not found or not active.", workspace_id=workspace_id)
    conn = matches[0]

    # ---- rate limit / quotas ----
    per_key_min, per_key_day, ws_day = _usage_counts(logs, key_row.get("id"), workspace_id)
    if per_key_min >= int(key_row.get("requests_per_minute", 0)):
        _log("zendesk_search_tickets", key_row.get("id"), workspace_id, "error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Per-key rate limit exceeded.", requests_per_minute=key_row.get("requests_per_minute"), used_last_minute=per_key_min)
    if per_key_day >= int(key_row.get("daily_request_quota", 0)):
        _log("zendesk_search_tickets", key_row.get("id"), workspace_id, "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Per-key daily request quota exceeded.", daily_request_quota=key_row.get("daily_request_quota"), used_today=per_key_day)
    if ws_day >= int(ws.get("daily_request_quota", 0)):
        _log("zendesk_search_tickets", key_row.get("id"), workspace_id, "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Workspace daily request quota exceeded.", daily_request_quota=ws.get("daily_request_quota"), used_today=ws_day)

    # ---- search over local cache ----
    if not isinstance(tickets, list):
        tickets = []
    if not isinstance(comments, list):
        comments = []

    q = query.strip().lower()
    q_terms = [t for t in re.split(r"\s+", q) if t]

    def _text_contains(text):
        if not isinstance(text, str) or not text:
            return False
        tl = text.lower()
        return all(term in tl for term in q_terms)

    def _tags_match(ticket_tags):
        if not isinstance(ticket_tags, list):
            ticket_tags = []
        if tags_any is not None:
            if not any(t in ticket_tags for t in tags_any):
                return False
        if tags_all is not None:
            if not all(t in ticket_tags for t in tags_all):
                return False
        return True

    def _filters_match(t):
        if status is not None and t.get("status") not in set(status):
            return False
        if type is not None and t.get("type") not in set(type):
            return False
        if priority is not None and t.get("priority") not in set(priority):
            return False
        if requester_id is not None and t.get("requester_id") != requester_id:
            return False
        if assignee_id is not None and t.get("assignee_id") != assignee_id:
            return False
        if group_id is not None and t.get("group_id") != group_id:
            return False
        if updated_since_dt is not None:
            ts = _parse_ts(t.get("zendesk_updated_at") or t.get("updated_at"))
            if ts is None or ts < updated_since_dt:
                return False
        if not _tags_match(t.get("tags")):
            return False
        return True

    # comment index (by ticket_id) for include_comments
    comments_by_ticket = {}
    if include_comments:
        for c in comments:
            if not isinstance(c, dict):
                continue
            if c.get("workspace_id") != workspace_id:
                continue
            tid = c.get("ticket_id")
            if not tid:
                continue
            comments_by_ticket.setdefault(tid, []).append(c)

    def _relevance_score(t):
        score = 0
        if _text_contains(t.get("subject")):
            score += 5
        if _text_contains(t.get("description")):
            score += 3
        # tags: any term in tags boosts
        tg = t.get("tags") if isinstance(t.get("tags"), list) else []
        tl = " ".join([x for x in tg if isinstance(x, str)]).lower()
        for term in q_terms:
            if term in tl:
                score += 1
        if include_comments:
            for c in comments_by_ticket.get(t.get("id"), []):
                if _text_contains(c.get("body")):
                    score += 1
        return score

    matches = []
    for t in tickets:
        if not isinstance(t, dict):
            continue
        if t.get("workspace_id") != workspace_id:
            continue
        if not _filters_match(t):
            continue
        # must match query somewhere
        hit = _text_contains(t.get("subject")) or _text_contains(t.get("description"))
        if not hit:
            # tags search
            tg = t.get("tags") if isinstance(t.get("tags"), list) else []
            tl = " ".join([x for x in tg if isinstance(x, str)]).lower()
            hit = any(term in tl for term in q_terms)
        snippets = []
        if include_comments and not hit:
            for c in comments_by_ticket.get(t.get("id"), []):
                if _text_contains(c.get("body")):
                    hit = True
                    body = c.get("body") or ""
                    s = body if len(body) <= 200 else body[:200] + "…"
                    snippets.append({"comment_id": c.get("id"), "visibility": c.get("visibility"), "snippet": s})
        elif include_comments:
            # also include snippets if they match even when ticket matched
            for c in comments_by_ticket.get(t.get("id"), []):
                if _text_contains(c.get("body")):
                    body = c.get("body") or ""
                    s = body if len(body) <= 200 else body[:200] + "…"
                    snippets.append({"comment_id": c.get("id"), "visibility": c.get("visibility"), "snippet": s})
        if hit:
            row = {"ticket": t}
            if include_comments and snippets:
                row["comment_snippets"] = snippets
            matches.append(row)

    # sorting
    reverse = (sort_order == "desc")
    if sort_by == "relevance":
        matches.sort(key=lambda r: (_relevance_score(r["ticket"]), _parse_ts(r["ticket"].get("zendesk_updated_at") or r["ticket"].get("updated_at")) or now_dt), reverse=reverse)
    elif sort_by == "zendesk_updated_at":
        matches.sort(key=lambda r: (_parse_ts(r["ticket"].get("zendesk_updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=reverse)
    else:  # zendesk_created_at
        matches.sort(key=lambda r: (_parse_ts(r["ticket"].get("zendesk_created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=reverse)

    total = len(matches)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = matches[start:end]
    has_more = end < total

    # persist successful key use + request log
    if isinstance(api_keys, list):
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                api_keys[i] = k
                break
        _save("api_keys.json", api_keys)

    _log("zendesk_search_tickets", key_row.get("id"), workspace_id, "success")

    return {
        "results": page_rows,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
        "workspace": {"id": ws.get("id"), "name": ws.get("name"), "zendesk_subdomain": ws.get("zendesk_subdomain")},
        "connection": {"id": conn.get("id"), "auth_type": conn.get("auth_type"), "status": conn.get("status")}
    }

def zendesk_whoami(api_key, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0039000" if __import__("os").path.isdir("./environment_mix/0039000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, api_key_id, ws_id, status_s, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "zdrq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            **({"error_code": error_code} if error_code else {})
        })
        _save("request_logs.json", logs)

    def _usage_counts(logs, api_key_id, ws_id):
        per_key_min = per_key_day = ws_day = 0
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("created_at") or r.get("timestamp"))
            if ts is None:
                continue
            if api_key_id is not None and r.get("api_key_id") == api_key_id and ts >= minute_ago:
                per_key_min += 1
            if ts >= day_start:
                if api_key_id is not None and r.get("api_key_id") == api_key_id:
                    per_key_day += 1
                if ws_id is not None and r.get("workspace_id") == ws_id:
                    ws_day += 1
        return per_key_min, per_key_day, ws_day

    if not isinstance(api_key, str) or not re.match(r"^zdkey_[0-9A-Za-z]{24,}$", api_key):
        _log("zendesk_whoami", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid api_key format.", api_key=api_key)

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    key_row = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            # Authenticate against client-visible values (id or prefix), never hash
            if k.get("id") == api_key:
                key_row = k
                break
            if k.get("key_prefix") == api_key:
                key_row = k
                break

    if not key_row:
        _log("zendesk_whoami", None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key not recognized.")

    ws = None
    ws_id = key_row.get("workspace_id")
    if isinstance(workspaces, list):
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == ws_id:
                ws = w
                break
    if not ws:
        _log("zendesk_whoami", key_row.get("id"), ws_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found for API key.", api_key_id=key_row.get("id"), workspace_id=ws_id)

    if key_row.get("status") != "active":
        _log("zendesk_whoami", key_row.get("id"), ws_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active.", api_key_id=key_row.get("id"))
    if ws.get("status") != "active":
        _log("zendesk_whoami", key_row.get("id"), ws_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_id=ws_id)

    per_key_min, per_key_day, ws_day = _usage_counts(logs, key_row.get("id"), ws_id)

    # record successful usage
    if isinstance(api_keys, list):
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("id") == key_row.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                api_keys[i] = k
                break
        _save("api_keys.json", api_keys)

    _log("zendesk_whoami", key_row.get("id"), ws_id, "success")

    return {
        "identity": {
            "api_key_id": key_row.get("id"),
            "api_key_name": key_row.get("name"),
            "key_prefix": key_row.get("key_prefix"),
            "workspace": {
                "id": ws.get("id"),
                "name": ws.get("name"),
                "zendesk_subdomain": ws.get("zendesk_subdomain"),
                "default_locale": ws.get("default_locale"),
                "status": ws.get("status")
            },
            "status": key_row.get("status"),
            "scopes": ["tickets:read", "tickets:write", "comments:write", "search:read"]
        },
        "usage": {
            "requests_last_minute": per_key_min,
            "requests_today_for_key": per_key_day,
            "requests_today_for_workspace": ws_day,
            "limits": {
                "requests_per_minute": key_row.get("requests_per_minute"),
                "daily_request_quota_key": key_row.get("daily_request_quota"),
                "daily_request_quota_workspace": ws.get("daily_request_quota")
            }
        }
    }
